CREATE TYPE "FailoverState" AS ENUM ('LOCAL_ACTIVE','CLOUD_TAKEOVER_PENDING','CLOUD_ACTIVE','HANDOVER_PENDING','FAULT');
CREATE TABLE "failover_sessions" ("id" TEXT PRIMARY KEY,"site_id" TEXT NOT NULL,"state" "FailoverState" NOT NULL DEFAULT 'LOCAL_ACTIVE',"control_owner" TEXT NOT NULL DEFAULT 'local',"lease_epoch" BIGINT NOT NULL DEFAULT 0,"reason" TEXT,"started_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"ended_at" TIMESTAMP(3),"updated_at" TIMESTAMP(3) NOT NULL,CONSTRAINT "failover_sessions_site_id_fkey" FOREIGN KEY ("site_id") REFERENCES "sites"("id") ON DELETE CASCADE);
CREATE TABLE "failover_events" ("id" TEXT PRIMARY KEY,"site_id" TEXT NOT NULL,"session_id" TEXT,"state" "FailoverState" NOT NULL,"control_owner" TEXT NOT NULL,"lease_epoch" BIGINT NOT NULL,"reason" TEXT,"payload" JSONB,"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "failover_events_site_id_fkey" FOREIGN KEY ("site_id") REFERENCES "sites"("id") ON DELETE CASCADE,CONSTRAINT "failover_events_session_id_fkey" FOREIGN KEY ("session_id") REFERENCES "failover_sessions"("id") ON DELETE SET NULL);
CREATE TABLE "ev_sessions" ("id" TEXT PRIMARY KEY,"site_id" TEXT NOT NULL,"charger_id" TEXT NOT NULL,"connector_id" INTEGER NOT NULL DEFAULT 1,"status" TEXT NOT NULL,"active_power_w" INTEGER NOT NULL DEFAULT 0,"started_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"ended_at" TIMESTAMP(3),"updated_at" TIMESTAMP(3) NOT NULL,CONSTRAINT "ev_sessions_site_id_fkey" FOREIGN KEY ("site_id") REFERENCES "sites"("id") ON DELETE CASCADE);
CREATE TABLE "config_revisions" ("id" TEXT PRIMARY KEY,"site_id" TEXT NOT NULL,"revision" INTEGER NOT NULL,"payload" JSONB NOT NULL,"status" TEXT NOT NULL DEFAULT 'PENDING',"result" JSONB,"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"applied_at" TIMESTAMP(3),CONSTRAINT "config_revisions_site_id_fkey" FOREIGN KEY ("site_id") REFERENCES "sites"("id") ON DELETE CASCADE);
CREATE TABLE "alert_rules" ("id" TEXT PRIMARY KEY,"site_id" TEXT NOT NULL,"code" TEXT NOT NULL,"severity" "AlertSeverity" NOT NULL DEFAULT 'WARNING',"condition" JSONB NOT NULL,"debounce_sec" INTEGER NOT NULL DEFAULT 0,"cooldown_sec" INTEGER NOT NULL DEFAULT 300,"enabled" BOOLEAN NOT NULL DEFAULT true,"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" TIMESTAMP(3) NOT NULL,CONSTRAINT "alert_rules_site_id_fkey" FOREIGN KEY ("site_id") REFERENCES "sites"("id") ON DELETE CASCADE);
CREATE INDEX "failover_sessions_site_id_started_at_idx" ON "failover_sessions"("site_id","started_at");
CREATE INDEX "failover_events_site_id_created_at_idx" ON "failover_events"("site_id","created_at");
CREATE INDEX "ev_sessions_site_id_charger_id_started_at_idx" ON "ev_sessions"("site_id","charger_id","started_at");
CREATE UNIQUE INDEX "config_revisions_site_id_revision_key" ON "config_revisions"("site_id","revision");
CREATE UNIQUE INDEX "alert_rules_site_id_code_key" ON "alert_rules"("site_id","code");
